<div class="page-header"><div><span class="eyebrow">A GOOD THING, SHARED RESPONSIBLY</span><h1>Learning is better when it’s shared.</h1><p>Define clear conditions. Reward verified activity. Keep an audit trail.</p></div><span class="icon-tile orange"><?= icon('gift',25) ?></span></div><div class="two-column"><div class="stack"><section class="card table-card"><div class="card-pad" style="padding-bottom:0"><div class="card-header"><h2>Referral activity.</h2><span class="badge badge-neutral"><?= $total ?> records</span></div></div><?php if($referrals): ?><div class="table-responsive"><table class="data-table"><thead><tr><th>Referrer → friend</th><th>Status</th><th>Reward</th><th>Joined</th></tr></thead><tbody><?php foreach($referrals as $r): ?><tr><td><strong><?= e($r['referrer']) ?></strong><small>Invited <?= e($r['referred']) ?> · Referral #<?= (int)$r['id'] ?></small></td><td><?= badge($r['status']) ?></td><td><?= $r['amount']!==null?number($r['amount']).' '.e(strtoupper($r['reward_type'])):'Not issued' ?></td><td><?= niceDate($r['created_at'],'M j, Y') ?></td></tr><?php endforeach; ?></tbody></table></div><?php pagination($total); ?><?php else:emptyState('gift','No invitations have qualified yet.','Learners can share unique links. Reward records only appear after configured conditions are met.');endif; ?></section><section class="card form-card"><h2 class="form-section-title">Resolve a concern with a reason.</h2><p class="form-section-description">Rechecking never bypasses eligibility rules. Issued rewards are immutable and cannot be silently removed.</p><form action="<?= e(route_url('/api/admin/referrals/0')) ?>" method="post" data-referral-resolve><?= csrfField() ?><div class="field"><label for="referral-id">Referral record</label><select id="referral-id" name="referral_id" required><option value="">Choose a record to review</option><?php foreach($referrals as $r):if($r['status']==='rewarded')continue; ?><option value="<?= (int)$r['id'] ?>">#<?= (int)$r['id'] ?> · <?= e($r['referrer']) ?> → <?= e($r['referred']) ?></option><?php endforeach; ?></select></div><div class="field"><label for="referral-action">Action</label><select id="referral-action" name="action"><option value="recheck">Recheck configured eligibility</option><option value="reject">Reject as ineligible / suspicious</option></select></div><div class="field"><label for="referral-reason">Reason</label><textarea id="referral-reason" name="reason" minlength="10" maxlength="500" required></textarea></div><button class="btn btn-secondary">Record decision <?= icon('shield',15) ?></button></form></section></div>
<aside class="card form-card"><h2 class="form-section-title">A clear, honest campaign.</h2><p class="form-section-description">Only platform XP or virtual coins are supported. No real-money reward or payout is configured.</p><form action="<?= e(route_url('/api/admin/campaign')) ?>" method="post" data-api><?= csrfField() ?><div class="field"><label for="campaign-title">Campaign name</label><input id="campaign-title" name="title" required minlength="3" maxlength="160" value="<?= e($campaign['title']??'Learn together') ?>"></div><div class="field"><label for="reward-type">Reward type</label><select id="reward-type" name="reward_type"><option value="xp" <?= ($campaign['reward_type']??'xp')==='xp'?'selected':'' ?>>Experience points (XP)</option><option value="coins" <?= ($campaign['reward_type']??'')==='coins'?'selected':'' ?>>Virtual coins · no cash value</option></select></div><?php foreach(['referrer_reward'=>['Referring learner reward',0,10000,50],'referred_reward'=>['Referred learner reward',0,10000,0],'qualifying_lessons'=>['Required completed lessons',1,100,3],'max_rewards'=>['Maximum rewards per referrer',1,1000,20]] as $key=>[$label,$min,$max,$default]): ?><div class="field"><label for="<?= $key ?>"><?= $label ?></label><input id="<?= $key ?>" name="<?= $key ?>" type="number" min="<?= $min ?>" max="<?= $max ?>" value="<?= (int)($campaign[$key]??$default) ?>" required></div><?php endforeach; ?><div class="field"><label for="starts-at">Campaign start <span>· UTC, optional</span></label><input id="starts-at" name="starts_at" type="datetime-local" value="<?= !empty($campaign['starts_at'])?e(date('Y-m-d\TH:i',strtotime($campaign['starts_at']))):'' ?>"></div><div class="field"><label for="ends-at">Campaign end <span>· UTC, optional</span></label><input id="ends-at" name="ends_at" type="datetime-local" value="<?= !empty($campaign['ends_at'])?e(date('Y-m-d\TH:i',strtotime($campaign['ends_at']))):'' ?>"></div><div class="checkbox-list"><label class="checkbox-label"><input type="checkbox" name="require_verified" value="1" <?= ($campaign['require_verified']??1)?'checked':'' ?>><span>Require the referred learner’s verified email.</span></label><label class="checkbox-label"><input type="checkbox" name="enabled" value="1" <?= !empty($campaign['enabled'])?'checked':'' ?>><span>Enable this campaign and display its configured rewards.</span></label></div><div class="form-actions"><button class="btn btn-primary">Save campaign rules</button></div></form><p class="fine-print" style="margin-top:17px">Verified-email conditions cannot be satisfied by unverified users when email delivery is disabled. Accounts are unique by normalised email; multi-identity abuse still requires human fraud review.</p></aside></div>
